use nes_emu::{cart::Cart,cpu::Nes};
use std::{env,fs};
fn main(){let args:Vec<_>=env::args().collect();let rom=fs::read(&args[1]).unwrap();let mut n=Nes::new(Cart::load(&rom).unwrap());let frames:usize=args[2].parse().unwrap();let out=args.get(3).map(String::as_str).unwrap_or("/tmp/ours");fs::create_dir_all(out).unwrap();let mut changes=Vec::new();if let Some(p)=args.get(4){for line in fs::read_to_string(p).unwrap().lines(){let line=line.split('#').next().unwrap();let w:Vec<_>=line.split_whitespace().collect();if w.len()==2{changes.push((w[0].parse::<usize>().unwrap(),u8::from_str_radix(w[1].trim_start_matches("0x"),16).unwrap()))}}}let mut audio=Vec::new();for frame in 0..frames{for &(f,k) in &changes{if f==frame{n.set_keys(k)}}n.run_frame();let mut bytes=Vec::with_capacity(122880);for &p in &n.ppu.fb{bytes.extend_from_slice(&p.to_le_bytes())}if env::var_os("LAST_ONLY").is_none()||frame==frames-1{fs::write(format!("{out}/frame_{frame:05}.idx"),bytes).unwrap();}n.apu.drain();for &p in &n.apu.drained{audio.extend_from_slice(&p.to_le_bytes())}}fs::write(format!("{out}/audio.raw"),audio).unwrap();println!("frames={} cycles={} pc={:04x} status={} signature={:02x?} log={}",frames,n.cycles,n.pc,n.cart.ram[0],&n.cart.ram[1..4],String::from_utf8_lossy(&n.cart.ram[4..1024]).split('\0').next().unwrap());}
